"""Closed commerce file lifecycle contracts API-111/112/113/132."""
def extend(spec):
    from authorization import object_schema, parameter, operation, REF, UUID, VERSION
    schemas = spec['components']['schemas']
    checksum = {'type': 'string', 'pattern': '^[a-f0-9]{64}$'}
    https = {'type': 'string', 'format': 'uri', 'pattern': '^https://'}
    instant = {'type': 'string', 'format': 'date-time'}
    schemas['FileUpload'] = {**object_schema({'purpose': {'enum': ['IMAGE', 'BROCHURE']}, 'filename': {'type': 'string', 'minLength': 1, 'maxLength': 120, 'description': 'Display only; NFC, no control/format characters or paths. Never part of a storage key.'}, 'mimeType': {'enum': ['image/jpeg', 'image/png', 'image/webp', 'application/pdf']}, 'size': {'type': 'integer', 'format': 'int64', 'minimum': 1, 'maximum': 10485760}, 'checksumSha256': checksum, 'linkedResourceId': UUID}), 'required': ['purpose', 'filename', 'mimeType', 'size', 'checksumSha256'], 'description': 'IMAGE <=5MiB JPEG/PNG/WebP; BROCHURE <=10MiB PDF. SHIPPING_LABEL is generated by trusted carrier results only. linkedResourceId resolves an owned product/SKU; detached uploads are creator-only.'}
    schemas['FileUploadResult'] = object_schema({'assetId': UUID, 'uploadUrl': https, 'requiredHeaders': {'type': 'object', 'maxProperties': 20, 'additionalProperties': {'type': 'string', 'maxLength': 1000}}, 'expiresAt': instant})
    schemas['FileCompletion'] = object_schema({'checksumSha256': checksum})
    schemas['AssetDTO'] = object_schema({'id': UUID, 'state': {'enum': ['UPLOADING', 'QUARANTINED', 'CLEAN', 'PUBLISHED', 'REJECTED']}, 'purpose': {'enum': ['IMAGE', 'BROCHURE', 'SHIPPING_LABEL']}, 'mimeType': {'type': 'string', 'maxLength': 100}, 'size': {'type': 'integer', 'format': 'int64', 'minimum': 1}, 'checksum': checksum, 'url': {'anyOf': [https, {'type': 'null'}]}, 'version': VERSION})
    schemas['FileDownload'] = object_schema({'url': https, 'expiresAt': instant})
    schemas['FileScanResult'] = {**object_schema({'commandId': UUID, 'checksumSha256': checksum, 'result': {'enum': ['CLEAN', 'REJECTED']}, 'scannerVersion': {'type': 'string', 'pattern': '^[A-Za-z0-9][A-Za-z0-9._:+-]{0,99}$'}, 'reasonCode': {'type': 'string', 'pattern': '^[A-Z][A-Z0-9_]{0,99}$'}}), 'required': ['commandId', 'checksumSha256', 'result', 'scannerVersion']}
    spec['components']['securitySchemes']['integrationWorkload'] = {'type': 'oauth2', 'flows': {'clientCredentials': {'tokenUrl': '/realms/nigson/protocol/openid-connect/token', 'scopes': {'files.scan.write': 'Integration-owned scan-result application'}}}, 'description': 'Private ingress, exact Keycloak issuer/audience/client/scope. No browser cookies or signed user actor.'}
    routes = [(111, 'post', '/api/v1/commerce/files/uploads', 'FileUpload', 'FileUploadResult', 201, False), (112, 'post', '/api/v1/commerce/files/{id}/completion', 'FileCompletion', 'AssetDTO', 202, True), (113, 'get', '/api/v1/commerce/files/{id}/download', None, 'FileDownload', 200, False), (132, 'post', '/internal/v1/files/{id}/scan-result', 'FileScanResult', 'AssetDTO', 200, True)]
    descriptions = {111: 'Current CONTENT_EDITOR and purpose/resource ownership. Persist UPLOADING intent before signing. Five-minute constrained HTTPS upload: exact size/MIME/SHA256/owner metadata/encryption and conditional non-overwrite. No public URL before scan. Matching command replay returns original capability, whose expiry remains authoritative.', 112: 'Current CONTENT_EDITOR, same owner/purpose and expected asset version. HEAD outside DB transaction verifies size/MIME/SHA256/owner/encryption and pins storage version/ETag. Atomically QUARANTINED, audit and EVT-025. 202 AssetDTO and Location identify durable download gate; download remains unavailable until clean.', 113: 'Current CONTENT_EDITOR and related resource or detached creator ownership; generated PRIVATE shipment labels require current OPERATIONS. CLEAN/PUBLISHED only. Audited grant, 60-second HTTPS signed URL, no-store; provider/signing outside DB locks. Unknown query/body denied.', 132: 'Private SERVICE_INTEGRATION:files.scan.write; exact configured workload client and commandId equal emitted scan event ID. Same asset/checksum/pinned version. First completion version1; stable scan business key suppresses duplicate effects, contradictory terminal body409. Persist copy lease/hash before unlocked conditional pinned-version S3 copy; uncertain outcome stays UNKNOWN/quarantined and reconciles final-object HEAD without blind recopy. CLEAN/REJECTED outcome, audit and durable response commit together; no browser result accepted.'}
    for number, method, path, request, response, status, versioned in routes:
        params = []
        if '{id}' in path:
            params.append(parameter('id', 'path', UUID, True))
        if request:
            params.append(parameter('Idempotency-Key', 'header', {'type': 'string', 'minLength': 1, 'maxLength': 100, 'pattern': '^[ -~]+$'}, True))
            if number != 132:
                params.append(parameter('X-CSRF-TOKEN', 'header', {'type': 'string', 'minLength': 43, 'maxLength': 43}, True))
        if versioned:
            params.append(parameter('If-Match', 'header', {'type': 'string', 'pattern': '^"(0|[1-9][0-9]{0,18})"$'}, True))
        op = operation(f'API-{number:03}', descriptions[number], response, params)
        if status != 200:
            op['responses'][str(status)] = op['responses'].pop('200')
        op['responses']['503'] = {'description': 'Provider unavailable or copy outcome UNKNOWN; inspect durable existing operation, do not blindly repeat side effects.', 'content': {'application/problem+json': {'schema': {'$ref': '../problem/problem.schema.json'}}}}
        op['responses'][str(status)]['headers'] = {'Cache-Control': {'schema': {'const': 'no-store'}}}
        if number != 113:
            op['responses'][str(status)]['headers']['ETag'] = {'schema': {'type': 'string'}}
        if status in (201, 202):
            op['responses'][str(status)]['headers']['Location'] = {'schema': {'type': 'string'}}
        if request:
            op['requestBody'] = {'required': True, 'content': {'application/json': {'schema': REF(request)}}}
        if number == 132:
            op['security'] = [{'integrationWorkload': ['files.scan.write']}]
        spec['paths'].setdefault(path, {})[method] = op
    return spec
